using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderTransportOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private readonly PhysicsCollisionWorldOperations _collision=new();private readonly PowderFluidOperations _fluid=new();private readonly DestructionDefinitionOperations _definition=new();
    private static Variant Get(Settings data,string key,Variant fallback=default)=>data.TryGetValue(key,out var value)?value:fallback;private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();
    private sealed class State
    {
        internal Settings Data,Deposits;internal Vector3[] Points,Velocities;internal byte[] Phase;internal float[] Masses,Radii,Compaction,Sleep,Settle;internal int[] Ids;
        internal State(Settings data){Data=data;Deposits=data["powder_deposits"].AsGodotDictionary();Points=data["points"].AsVector3Array();Velocities=data["velocities"].AsVector3Array();Phase=data["powder_phase"].AsByteArray();Masses=data["powder_masses"].AsFloat32Array();Radii=data["powder_radii"].AsFloat32Array();Compaction=data["powder_compaction"].AsFloat32Array();Sleep=data["powder_sleep"].AsFloat32Array();Settle=data["powder_settle"].AsFloat32Array();Ids=data["powder_ids"].AsInt32Array();}
        internal void Release(int i,Vector3 velocity){Deposits.Remove(Ids[i]);Phase[i]=0;Velocities[i]=velocity;Sleep[i]=0;Settle[i]=0;Data["powder_releases"]=Get(Data,"powder_releases",0).AsInt64()+1;}
        internal void Commit(){Data["points"]=Points;Data["velocities"]=Velocities;Data["powder_phase"]=Phase;Data["powder_compaction"]=Compaction;Data["powder_sleep"]=Sleep;Data["powder_settle"]=Settle;}
    }
    public void fields(Resource definition,GArray rows){foreach(var value in rows){var row=value.AsGodotArray();string key=row[0].AsString();var hints=row[3].AsGodotDictionary().Duplicate(true);if(key is not ("powder_deposition" or "powder_adhesion" or "powder_settling" or "powder_displacement" or "powder_erosion" or "powder_airborne"))hints["advanced"]=true;_definition.add(definition,key,row[1].AsString(),row[2],"Deposition & Transport",hints,true);}}
    public void release(Settings state,int index,Vector3 velocity){var data=new State(state);data.Release(index,velocity);data.Commit();}
    private Settings Config(RefCounted controller,string id,double time){var actor=Map(controller,"prototypes")[id].AsGodotDictionary()["actor"].As<Resource>();return _settings.sample(actor,controller.Call("_local",actor,time).AsDouble());}
    private static int ProxyIndex(string proxy)=>proxy.Contains(":p",StringComparison.Ordinal)?int.Parse(proxy.Split(":p",StringSplitOptions.None)[1]):-1;
    private static Settings ProxyBodies(RefCounted controller)=>Map(controller.Get("fluid").AsGodotObject().Get("proxies").AsGodotObject(),"bodies");
    public void before(RefCounted controller,GArray batches,double time,Settings motions)
    {
        foreach(var value in batches){var batch=value.AsGodotDictionary();if(!batch["moving"].AsBool())continue;var state=new State(batch["state"].AsGodotDictionary());var s=batch["settings"].AsGodotDictionary();var fluids=Get(s,"powder_erosion",true).AsBool()&&state.Deposits.Count>0?_fluid.fluids(controller,batch,time):new GArray();double clearAt=Get(s,"powder_clear_at",-1).AsDouble(),h=batch["h"].AsDouble();bool clear=clearAt>=0&&state.Data["powder_time"].AsDouble()>=clearAt&&!Get(state.Data,"powder_cleared",false).AsBool();if(clear)state.Data["powder_cleared"]=true;var gravity=batch["gravity"].AsVector3();for(int i=0;i<state.Points.Length;i++){if(state.Phase[i]!=1)continue;var deposit=state.Deposits.TryGetValue(state.Ids[i],out var item)?item.AsGodotDictionary():new Settings();string owner=Get(deposit,"actor","").AsString();var other=Get(Map(controller,"states"),owner,new Settings()).AsGodotDictionary();if(clear||!Get(s,"powder_deposition",false).AsBool()||other.Count==0||!Get(other,"active",false).AsBool()){state.Release(i,Vector3.Zero);continue;}var config=Config(controller,owner,time);if(!config["collision"].AsBool()||!config["powder_accumulation"].AsBool()){state.Release(i,Vector3.Zero);continue;}var pose=other["pose"].AsTransform3D();var next=pose*deposit["local"].AsVector3();var normal=(pose.Basis.Inverse().Transposed()*deposit["normal"].AsVector3()).Normalized();string proxy=Get(deposit,"proxy","").AsString();int index=ProxyIndex(proxy);var proxyBodies=ProxyBodies(controller);if(proxyBodies.ContainsKey(proxy)&&deposit.ContainsKey("proxy_local")){var proxyPose=PhysicsServer3D.BodyGetState(proxyBodies[proxy].AsGodotDictionary()["rid"].AsRid(),PhysicsServer3D.BodyState.Transform).AsTransform3D();next=proxyPose*deposit["proxy_local"].AsVector3();normal=proxyPose.Basis*deposit["proxy_normal"].AsVector3();}else{var otherPoints=other["points"].AsVector3Array();if(index>=0&&index<otherPoints.Length)next=otherPoints[index]+deposit["proxy_offset"].AsVector3();}var velocity=(next-state.Points[i])/(float)Math.Max(.000001,h);state.Points[i]=next;state.Velocities[i]=velocity;double mass=Math.Max(1e-9,state.Masses[i]),radius=state.Radii[i],g=gravity.Length()*s["gravity_scale"].AsDouble(),support=Math.Max(0,normal.Dot((-gravity).Normalized())),resistance=(Get(s,"powder_adhesion",0).AsDouble()+config["powder_adhesion"].AsDouble()+s["cohesion"].AsDouble()+mass*g*support*s["static_friction"].AsDouble())*(1+state.Compaction[i]);var relative=batch["wind"].AsVector3()-velocity;double force=.5*1.225*s["air_drag"].AsDouble()*Math.PI*radius*radius*relative.LengthSquared()*s["wind_influence"].AsDouble()*Get(s,"powder_wind_erosion",1).AsDouble();var transportVelocity=relative;foreach(var fluidValue in fluids){var fluid=fluidValue.AsGodotDictionary();var neighbors=_fluid.near(fluid,next);if(neighbors.Length==0)continue;var flow=Vector3.Zero;var fluidVelocities=fluid["state"].AsGodotDictionary()["velocities"].AsVector3Array();foreach(int j in neighbors)flow+=fluidVelocities[j]/neighbors.Length;var shear=flow-velocity;force+=.5*fluid["values"].AsGodotDictionary()["fluid_density"].AsDouble()*Math.PI*radius*radius*shear.LengthSquared()*s["fluid_strength"].AsDouble()*Get(s,"powder_fluid_erosion",1).AsDouble();transportVelocity+=shear;}double downhill=Math.Sqrt(Math.Max(0,1-support*support))*mass*g,ratio=(force+downhill)/Math.Max(1e-9,resistance);if(Get(s,"powder_erosion",true).AsBool())deposit["damage"]=Math.Max(0,Get(deposit,"damage",0).AsDouble()+(ratio-1)*h/Math.Max(.01,Get(s,"powder_erosion_resistance",1).AsDouble()));if(Get(deposit,"damage",0).AsDouble()>=Get(s,"powder_reactivation",.15).AsDouble()){state.Release(i,velocity+transportVelocity*.15f+normal*(float)Math.Min(1,Math.Sqrt(force/mass)*.05));continue;}if(Get(s,"powder_displacement",true).AsBool()){var settings=batch["config"].AsGodotDictionary();var hit=_collision.point_motion(controller.Get("world").As<RefCounted>(),batch["id"].AsString(),next,next,radius,settings["layer"].AsInt32(),settings["mask"].AsInt32(),new GArray{owner});var displacement=hit["position"].AsVector3()-next;var hits=hit["hits"].AsGodotArray();foreach(var contactValue in hits){var contact=contactValue.AsGodotDictionary();double depth=Math.Max(0,Get(contact,"depth",0).AsDouble()-.002);if(depth>displacement.Length())displacement=contact["normal"].AsVector3()*(float)Math.Min(depth,radius);}if(hits.Count>0&&displacement.Length()>radius*.02){string target=hits[0].AsGodotDictionary()["actor"].AsString();var movement=Get(motions,target,new Settings{["linear"]=Vector3.Zero}).AsGodotDictionary()["linear"].AsVector3();if(movement.Length()+displacement.Length()/Math.Max(.000001,h)>Get(s,"powder_displacement_resistance",.2).AsDouble()){state.Points[i]=next+displacement;state.Release(i,velocity+movement);continue;}}}state.Compaction[i]=(float)Math.Min(1,state.Compaction[i]+Get(s,"powder_deposit_compaction",.3).AsDouble()*h*.1);}state.Commit();}
    }
}
